require('dotenv').config();

if (process.env.NODE_ENV === 'production' && !process.env.JWT_SECRET) {
  throw new Error('FATAL ERROR: JWT_SECRET is not defined in production environment. Please set JWT_SECRET in your .env file.');
}

// Generate secure random secret for development if not provided
const getJWTSecret = () => {
  if (process.env.JWT_SECRET) {
    return process.env.JWT_SECRET;
  }

  // Only allow fallback in development
  if (process.env.NODE_ENV === 'production') {
    throw new Error('JWT_SECRET must be defined in production');
  }

  // Generate a random secret for development (warning logged)
  const crypto = require('crypto');
  const randomSecret = crypto.randomBytes(64).toString('hex');
  console.warn('⚠️  WARNING: Using auto-generated JWT_SECRET for development. Set JWT_SECRET in .env for production!');
  return randomSecret;
};

const jwtConfig = {
  // Secret key for signing tokens
  // IMPORTANT: Generate secure secret with: node -e "console.log(require('crypto').randomBytes(64).toString('hex'))"
  secret: getJWTSecret(),

  // Token expiration time
  expiresIn: process.env.JWT_EXPIRATION || '24h', // Options: '15m', '1h', '24h', '7d'

  // Refresh token expiration (longer than access token)
  refreshExpiresIn: process.env.JWT_REFRESH_EXPIRATION || '7d',

  // JWT algorithm
  algorithm: 'HS256',

  // Issuer (optional)
  issuer: 'ai-school-dashboard',

  // Audience (optional)
  audience: 'school-users',
};

/**
 * Password Hashing Configuration (bcrypt)
 */
const passwordConfig = {
  // Salt rounds for bcrypt (higher = more secure but slower)
  // Recommended: 10-12 for production
  saltRounds: parseInt(process.env.BCRYPT_ROUNDS, 10) || 12,

  // Minimum password requirements
  minLength: 8,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecialChar: false,
};

/**
 * Session Configuration (if using sessions)
 * ✅ SECURITY FIX: Require strong session secret in production
 */
const getSessionSecret = () => {
  if (process.env.SESSION_SECRET) {
    return process.env.SESSION_SECRET;
  }

  // Only allow fallback in development
  if (process.env.NODE_ENV === 'production') {
    throw new Error('SESSION_SECRET must be defined in production');
  }

  // Generate a random secret for development (warning logged)
  const crypto = require('crypto');
  const randomSecret = crypto.randomBytes(64).toString('hex');
  console.warn('⚠️  WARNING: Using auto-generated SESSION_SECRET for development. Set SESSION_SECRET in .env for production!');
  return randomSecret;
};

const sessionConfig = {
  secret: getSessionSecret(),
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: process.env.NODE_ENV === 'production', // HTTPS only in production
    httpOnly: true, // Prevent XSS attacks
    maxAge: 24 * 60 * 60 * 1000, // 24 hours
  },
};

/**
 * CORS Configuration
 */
const corsConfig = {
  // Allowed origins (frontend URLs)
  origin: process.env.CORS_ORIGIN
    ? process.env.CORS_ORIGIN.split(',')
    : ['http://localhost:3000', 'http://localhost:3001'],

  // Allow credentials (cookies, authorization headers)
  credentials: true,

  // Allowed HTTP methods
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],

  // Allowed headers
  allowedHeaders: ['Content-Type', 'Authorization'],

  // How long to cache preflight requests (in seconds)
  maxAge: 86400, // 24 hours
};

/**
 * Rate Limiting Configuration
 */
const rateLimitConfig = {
  // Time window in milliseconds
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || 15 * 60 * 1000, // 15 minutes

  // Maximum requests per window
  max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS, 10) || 100,

  // Error message
  message: 'Too many requests from this IP, please try again later.',

  // Return rate limit info in headers
  standardHeaders: true,
  legacyHeaders: false,
};

/**
 * Role-based access control
 */
const roles = {
  ADMIN: 'admin',
  TEACHER: 'teacher',
  PARENT: 'parent',
  STUDENT: 'student',
};

/**
 * Role hierarchy (for permission checks)
 * Higher level includes all lower level permissions
 */
const roleHierarchy = {
  admin: ['admin', 'teacher', 'parent', 'student'],
  teacher: ['teacher', 'student'],
  parent: ['parent'],
  student: ['student'],
};

module.exports = {
  jwtConfig,
  passwordConfig,
  sessionConfig,
  corsConfig,
  rateLimitConfig,
  roles,
  roleHierarchy,
};

/**
 * Socket.io Configuration
 * =======================
 * Real-time notification system setup
 */

const { Server } = require('socket.io');
const jwt = require('jsonwebtoken');
const { User } = require('../models');

/**
 * Initialize Socket.io server
 */
function initializeSocket(httpServer) {
  const io = new Server(httpServer, {
    cors: {
      origin: process.env.CORS_ORIGIN ? process.env.CORS_ORIGIN.split(',') : ['http://localhost:3000', 'http://localhost:5001'],
      methods: ['GET', 'POST'],
      credentials: true,
    },
  });

  // Authentication middleware
  io.use(async (socket, next) => {
    try {
      const { token } = socket.handshake.auth;

      if (!token) {
        return next(new Error('Authentication token required'));
      }

      // Verify JWT token
      const decoded = jwt.verify(token, process.env.JWT_SECRET);

      // Get user from database
      const user = await User.findByPk(decoded.id);

      if (!user) {
        return next(new Error('User not found'));
      }

      // Attach user to socket
      // eslint-disable-next-line no-param-reassign
      socket.user = {
        id: user.id,
        email: user.email,
        role: user.role,
      };

      return next();
    } catch (error) {
      console.error('Socket authentication error:', error);
      return next(new Error('Authentication failed'));
    }
  });

  // Connection handling
  io.on('connection', (socket) => {
    const userId = socket.user.id;
    console.log(`✅ User connected: ${socket.user.email} (${userId})`);

    // Join user-specific room
    socket.join(`user_${userId}`);

    // Join role-specific room
    socket.join(`role_${socket.user.role}`);

    // Handle client requesting notification count
    socket.on('request_notification_count', async () => {
      try {
        const { Notification } = require('../models');
        const count = await Notification.getUnreadCount(userId);
        socket.emit('notification_count', count);
      } catch (error) {
        console.error('Error getting notification count:', error);
      }
    });

    // Handle mark notification as read
    socket.on('mark_notification_read', async (notificationId) => {
      try {
        const { Notification } = require('../models');
        const notification = await Notification.findOne({
          where: { id: notificationId, user_id: userId },
        });

        if (notification) {
          await notification.markAsRead();
          const count = await Notification.getUnreadCount(userId);
          socket.emit('notification_count', count);
        }
      } catch (error) {
        console.error('Error marking notification as read:', error);
      }
    });

    // Handle mark all as read
    socket.on('mark_all_read', async () => {
      try {
        const { Notification } = require('../models');
        await Notification.markAllAsRead(userId);
        socket.emit('notification_count', 0);
        socket.emit('all_notifications_read');
      } catch (error) {
        console.error('Error marking all as read:', error);
      }
    });

    // Handle disconnection
    socket.on('disconnect', () => {
      console.log(`👋 User disconnected: ${socket.user.email}`);
    });
  });

  // Add helper method to emit to specific user
  io.emitToUser = (userId, event, data) => {
    io.to(`user_${userId}`).emit(event, data);
  };

  // Add helper method to emit to role
  io.emitToRole = (role, event, data) => {
    io.to(`role_${role}`).emit(event, data);
  };

  console.log('✅ Socket.io server initialized');
  return io;
}

module.exports = { initializeSocket };

/**
 * Assignment Controller
 * =====================
 * Handles assignment CRUD and submission management
 */

const assignmentService = require('../services/assignmentService');
const { catchAsync } = require('../middleware/errorHandler');

/**
 * Create assignment (Teacher only)
 */
exports.createAssignment = catchAsync(async (req, res) => {
  const { questions, ...assignmentData } = req.body;
  const teacherId = req.user.teacherProfile?.id;

  if (!teacherId) {
    return res.status(403).json({
      success: false,
      message: 'Chỉ giáo viên mới có thể tạo bài tập',
    });
  }

  const { io } = req.app.locals;
  const assignment = await assignmentService.createAssignment(assignmentData, questions, teacherId, io);

  return res.status(201).json({
    success: true,
    data: assignment,
  });
});

/**
 * Get assignment by ID
 */
exports.getAssignment = catchAsync(async (req, res) => {
  const assignment = await assignmentService.getAssignmentById(req.params.id);

  if (!assignment) {
    return res.status(404).json({
      success: false,
      message: 'Không tìm thấy bài tập',
    });
  }

  return res.json({
    success: true,
    data: assignment,
  });
});

/**
 * Get assignments by course
 */
exports.getAssignmentsByCourse = catchAsync(async (req, res) => {
  const { courseId } = req.params;
  const assignments = await assignmentService.getAssignmentsByCourse(courseId, req.query);

  return res.json({
    success: true,
    data: assignments,
  });
});

/**
 * Get student's assignments
 */
exports.getStudentAssignments = catchAsync(async (req, res) => {
  const studentId = req.user.studentProfile?.id;

  if (!studentId) {
    return res.status(403).json({
      success: false,
      message: 'Chỉ học sinh mới có thể xem bài tập của mình',
    });
  }

  const assignments = await assignmentService.getStudentAssignments(studentId);

  return res.json({
    success: true,
    data: assignments,
  });
});

/**
 * Update assignment
 */
exports.updateAssignment = catchAsync(async (req, res) => {
  const { Assignment } = require('../models');
  const teacherId = req.user.teacherProfile?.id;

  const assignment = await Assignment.findByPk(req.params.id);

  if (!assignment || assignment.teacher_id !== teacherId) {
    return res.status(404).json({
      success: false,
      message: 'Không tìm thấy bài tập',
    });
  }

  await assignment.update(req.body);

  return res.json({
    success: true,
    data: assignment,
  });
});

/**
 * Delete assignment
 */
exports.deleteAssignment = catchAsync(async (req, res) => {
  const { Assignment } = require('../models');
  const teacherId = req.user.teacherProfile?.id;

  const assignment = await Assignment.findByPk(req.params.id);

  if (!assignment || assignment.teacher_id !== teacherId) {
    return res.status(404).json({
      success: false,
      message: 'Không tìm thấy bài tập',
    });
  }

  await assignment.destroy();

  return res.json({
    success: true,
    message: 'Đã xóa bài tập',
  });
});

/**
 * Publish assignment
 */
exports.publishAssignment = catchAsync(async (req, res) => {
  const teacherId = req.user.teacherProfile?.id;
  const { io } = req.app.locals;

  const assignment = await assignmentService.publishAssignment(req.params.id, teacherId, io);

  return res.json({
    success: true,
    data: assignment,
    message: 'Đã phát hành bài tập',
  });
});

/**
 * Start assignment (create submission)
 */
exports.startAssignment = catchAsync(async (req, res) => {
  const studentId = req.user.studentProfile?.id;

  if (!studentId) {
    return res.status(403).json({
      success: false,
      message: 'Chỉ học sinh mới có thể làm bài',
    });
  }

  const submission = await assignmentService.startAssignment(req.params.id, studentId);

  return res.status(201).json({
    success: true,
    data: submission,
  });
});

/**
 * Submit assignment
 */
exports.submitAssignment = catchAsync(async (req, res) => {
  const studentId = req.user.studentProfile?.id;
  const { submissionId, answers } = req.body;

  if (!studentId) {
    return res.status(403).json({
      success: false,
      message: 'Chỉ học sinh mới có thể nộp bài',
    });
  }

  const submission = await assignmentService.submitAssignment(submissionId, answers, studentId);

  return res.json({
    success: true,
    data: submission,
    message: 'Đã nộp bài thành công',
  });
});

/**
 * Grade submission (Teacher only)
 */
exports.gradeSubmission = catchAsync(async (req, res) => {
  const teacherId = req.user.teacherProfile?.id;
  const { gradedAnswers, feedback } = req.body;
  const { io } = req.app.locals;

  if (!teacherId) {
    return res.status(403).json({
      success: false,
      message: 'Chỉ giáo viên mới có thể chấm bài',
    });
  }

  const submission = await assignmentService.gradeSubmission(
    req.params.submissionId,
    gradedAnswers,
    feedback,
    teacherId,
    io,
  );

  return res.json({
    success: true,
    data: submission,
    message: 'Đã chấm bài thành công',
  });
});

/**
 * Get submissions for grading (Teacher only)
 */
exports.getSubmissionsForGrading = catchAsync(async (req, res) => {
  const teacherId = req.user.teacherProfile?.id;

  if (!teacherId) {
    return res.status(403).json({
      success: false,
      message: 'Chỉ giáo viên mới có quyền truy cập',
    });
  }

  const submissions = await assignmentService.getSubmissionsForGrading(req.params.id, teacherId);

  return res.json({
    success: true,
    data: submissions,
  });
});

/**
 * Get assignment statistics
 */
exports.getAssignmentStatistics = catchAsync(async (req, res) => {
  const stats = await assignmentService.getAssignmentStatistics(req.params.id);

  return res.json({
    success: true,
    data: stats,
  });
});

const { Op } = require('sequelize');
const {
  Attendance, Student, Course, Teacher, User,
} = require('../models');
const {
  catchAsync, NotFoundError, ValidationError, AuthorizationError,
} = require('../middleware/errorHandler');

/**
 * @route   GET /api/attendance
 * @desc    Get all attendance records with pagination and filtering
 * @access  Teacher, Admin
 */
exports.getAllAttendance = catchAsync(async (req, res) => {
  // Pagination
  const page = parseInt(req.query.page, 10) || 1;
  const limit = parseInt(req.query.limit, 10) || 50;
  const offset = (page - 1) * limit;

  // Filtering
  const where = {};

  if (req.query.student_id) {
    where.student_id = req.query.student_id;
  }

  if (req.query.course_id) {
    where.course_id = req.query.course_id;
  }

  if (req.query.status) {
    where.status = req.query.status;
  }

  // Date filtering
  if (req.query.date) {
    where.date = req.query.date;
  } else if (req.query.start_date && req.query.end_date) {
    where.date = {
      [Op.between]: [req.query.start_date, req.query.end_date],
    };
  }

  // ✅ FIXED: For students, only show their own attendance
  if (req.user.role === 'student') {
    const student = await Student.findOne({ where: { user_id: req.user.id } });
    if (student) {
      where.student_id = student.id;
    } else {
      // Student profile not found, return empty
      return res.json({
        success: true,
        data: {
          attendance: [],
          pagination: {
            total: 0, page: 1, pages: 0, limit,
          },
        },
      });
    }
  }

  // For teachers, only show attendance for their courses
  if (req.user.role === 'teacher') {
    const teacher = await Teacher.findOne({ where: { user_id: req.user.id } });
    if (teacher) {
      const teacherCourses = await Course.findAll({
        where: { teacher_id: teacher.id },
        attributes: ['id'],
      });
      where.course_id = { [Op.in]: teacherCourses.map((c) => c.id) };
    }
  }

  // Sorting
  const order = [['date', 'DESC'], ['created_at', 'DESC']];

  // Include related data
  const include = [
    {
      model: Student,
      as: 'student',
      attributes: ['id', 'first_name', 'last_name'],
      include: [{
        model: User,
        as: 'user',
        attributes: ['email'],
      }],
    },
    {
      model: Course,
      as: 'course',
      attributes: ['id', 'name', 'code', 'subject'],
    },
    {
      model: User,
      as: 'marker',
      attributes: ['id', 'email', 'role'],
    },
  ];

  const { rows: attendance, count } = await Attendance.findAndCountAll({
    where,
    include,
    limit,
    offset,
    order,
    distinct: true,
  });

  return res.json({
    success: true,
    data: {
      attendance,
      pagination: {
        total: count,
        page,
        pages: Math.ceil(count / limit),
        limit,
      },
    },
  });
});

/**
 * @route   GET /api/attendance/:id
 * @desc    Get attendance record by ID
 * @access  Teacher (own courses), Admin
 */
exports.getAttendanceById = catchAsync(async (req, res) => {
  const { id } = req.params;

  const attendance = await Attendance.findByPk(id, {
    include: [
      {
        model: Student,
        as: 'student',
        attributes: ['id', 'first_name', 'last_name'],
        include: [{
          model: User,
          as: 'user',
          attributes: ['email'],
        }],
      },
      {
        model: Course,
        as: 'course',
        attributes: ['id', 'name', 'code', 'subject', 'teacher_id'],
      },
      {
        model: User,
        as: 'marker',
        attributes: ['id', 'email', 'role'],
      },
    ],
  });

  if (!attendance) {
    throw new NotFoundError('Attendance record not found');
  }

  // Check permissions - teachers can only view attendance for their courses
  if (req.user.role === 'teacher') {
    const teacher = await Teacher.findOne({ where: { user_id: req.user.id } });
    if (!teacher || attendance.course.teacher_id !== teacher.id) {
      throw new AuthorizationError('You can only view attendance for your courses');
    }
  }

  res.json({
    success: true,
    data: { attendance },
  });
});

/**
 * @route   POST /api/attendance
 * @desc    Mark attendance (create new record)
 * @access  Teacher (own courses), Admin
 */
exports.markAttendance = catchAsync(async (req, res) => {
  const {
    student_id,
    course_id,
    date,
    status,
    notes,
    check_in_time,
    check_out_time,
  } = req.body;

  // Validate required fields
  if (!student_id || !course_id || !date || !status) {
    throw new ValidationError('Student, course, date, and status are required');
  }

  // Verify student exists
  const student = await Student.findByPk(student_id);
  if (!student) {
    throw new NotFoundError('Student not found');
  }

  // Verify course exists
  const course = await Course.findByPk(course_id);
  if (!course) {
    throw new NotFoundError('Course not found');
  }

  // Check permissions - teachers can only mark attendance for their courses
  if (req.user.role === 'teacher') {
    const teacher = await Teacher.findOne({ where: { user_id: req.user.id } });
    if (!teacher || course.teacher_id !== teacher.id) {
      throw new AuthorizationError('You can only mark attendance for your own courses');
    }
  }

  // Check for duplicate attendance (same student, course, date)
  const existingAttendance = await Attendance.findOne({
    where: {
      student_id,
      course_id,
      date,
    },
  });

  if (existingAttendance) {
    throw new ValidationError(
      'Attendance for this student in this course on this date already exists. '
      + 'Please update the existing record instead.',
    );
  }

  // Create attendance record
  const newAttendance = await Attendance.create({
    student_id,
    course_id,
    date,
    status,
    notes: notes || null,
    check_in_time: check_in_time || null,
    check_out_time: check_out_time || null,
    marked_by: req.user.id,
  });

  // Fetch complete attendance data
  const attendanceData = await Attendance.findByPk(newAttendance.id, {
    include: [
      { model: Student, as: 'student', attributes: ['id', 'first_name', 'last_name'] },
      { model: Course, as: 'course', attributes: ['id', 'name', 'code'] },
    ],
  });

  res.status(201).json({
    success: true,
    message: 'Attendance marked successfully',
    data: { attendance: attendanceData },
  });
});

/**
 * @route   PUT /api/attendance/:id
 * @desc    Update attendance record
 * @access  Teacher (own courses), Admin
 */
exports.updateAttendance = catchAsync(async (req, res) => {
  const { id } = req.params;

  const attendance = await Attendance.findByPk(id, {
    include: [{ model: Course, as: 'course' }],
  });

  if (!attendance) {
    throw new NotFoundError('Attendance record not found');
  }

  // Check permissions
  if (req.user.role === 'teacher') {
    const teacher = await Teacher.findOne({ where: { user_id: req.user.id } });
    if (!teacher || attendance.course.teacher_id !== teacher.id) {
      throw new AuthorizationError('You can only update attendance for your own courses');
    }
  }

  // Fields that can be updated
  const allowedFields = [
    'status', 'notes', 'check_in_time', 'check_out_time',
  ];

  const updates = {};
  allowedFields.forEach((field) => {
    if (req.body[field] !== undefined) {
      updates[field] = req.body[field];
    }
  });

  // Update marked_by to current user
  updates.marked_by = req.user.id;

  await attendance.update(updates);

  // Fetch updated data with associations
  const updatedAttendance = await Attendance.findByPk(id, {
    include: [
      { model: Student, as: 'student', attributes: ['id', 'first_name', 'last_name'] },
      { model: Course, as: 'course', attributes: ['id', 'name', 'code'] },
      { model: User, as: 'marker', attributes: ['id', 'email'] },
    ],
  });

  res.json({
    success: true,
    message: 'Attendance updated successfully',
    data: { attendance: updatedAttendance },
  });
});

/**
 * @route   DELETE /api/attendance/:id
 * @desc    Delete attendance record
 * @access  Teacher (own courses), Admin
 */
exports.deleteAttendance = catchAsync(async (req, res) => {
  const { id } = req.params;

  const attendance = await Attendance.findByPk(id, {
    include: [{ model: Course, as: 'course' }],
  });

  if (!attendance) {
    throw new NotFoundError('Attendance record not found');
  }

  // Check permissions
  if (req.user.role === 'teacher') {
    const teacher = await Teacher.findOne({ where: { user_id: req.user.id } });
    if (!teacher || attendance.course.teacher_id !== teacher.id) {
      throw new AuthorizationError('You can only delete attendance for your own courses');
    }
  }

  // Hard delete (attendance records can be removed)
  await attendance.destroy();

  res.json({
    success: true,
    message: 'Attendance deleted successfully',
    data: { deletedAttendanceId: id },
  });
});

/**
 * @route   GET /api/attendance/student/:studentId
 * @desc    Get attendance records for a specific student
 * @access  Student (self), Teacher, Admin
 */
exports.getStudentAttendance = catchAsync(async (req, res) => {
  const { studentId } = req.params;

  // Verify student exists
  const student = await Student.findByPk(studentId);
  if (!student) {
    throw new NotFoundError('Student not found');
  }

  // Check permissions
  const isStudent = req.user.role === 'student';

  if (isStudent) {
    const currentStudent = await Student.findOne({ where: { user_id: req.user.id } });
    if (!currentStudent || currentStudent.id !== studentId) {
      throw new AuthorizationError('You can only view your own attendance');
    }
  }

  // Filtering
  const where = { student_id: studentId };

  if (req.query.course_id) {
    where.course_id = req.query.course_id;
  }

  if (req.query.start_date && req.query.end_date) {
    where.date = {
      [Op.between]: [req.query.start_date, req.query.end_date],
    };
  }

  // Get attendance with course data
  const attendance = await Attendance.findAll({
    where,
    include: [{
      model: Course,
      as: 'course',
      attributes: ['id', 'name', 'code', 'subject'],
    }],
    order: [['date', 'DESC']],
  });

  // Calculate attendance rate
  const rate = await Attendance.calculateAttendanceRate(studentId, {
    startDate: req.query.start_date,
    endDate: req.query.end_date,
  });

  res.json({
    success: true,
    data: {
      student: {
        id: student.id,
        name: `${student.first_name} ${student.last_name}`,
      },
      attendance,
      rate,
      total: attendance.length,
      stats: rate,
    },
  });
});

/**
 * @route   GET /api/attendance/course/:courseId
 * @desc    Get attendance records for a specific course
 * @access  Teacher (own courses), Admin
 */
exports.getCourseAttendance = catchAsync(async (req, res) => {
  const { courseId } = req.params;

  // Verify course exists
  const course = await Course.findByPk(courseId);
  if (!course) {
    throw new NotFoundError('Course not found');
  }

  // Check permissions
  if (req.user.role === 'teacher') {
    const teacher = await Teacher.findOne({ where: { user_id: req.user.id } });
    if (!teacher || course.teacher_id !== teacher.id) {
      throw new AuthorizationError('You can only view attendance for your own courses');
    }
  }

  // Filtering
  const where = { course_id: courseId };

  if (req.query.date) {
    where.date = req.query.date;
  } else if (req.query.start_date && req.query.end_date) {
    where.date = {
      [Op.between]: [req.query.start_date, req.query.end_date],
    };
  }

  if (req.query.status) {
    where.status = req.query.status;
  }

  // Get attendance with student data
  const attendance = await Attendance.findAll({
    where,
    include: [{
      model: Student,
      as: 'student',
      attributes: ['id', 'first_name', 'last_name'],
      include: [{
        model: User,
        as: 'user',
        attributes: ['email'],
      }],
    }],
    order: [
      ['date', 'DESC'],
      [{ model: Student, as: 'student' }, 'last_name', 'ASC'],
    ],
  });

  // Get course statistics
  const stats = await Attendance.getCourseStats(courseId);

  res.json({
    success: true,
    data: {
      course: {
        id: course.id,
        name: course.name,
        code: course.code,
        subject: course.subject,
      },
      attendance,
      stats,
      total: attendance.length,
    },
  });
});

/**
 * @route   GET /api/attendance/date/:date
 * @desc    Get all attendance records for a specific date
 * @access  Teacher, Admin
 */
exports.getAttendanceByDate = catchAsync(async (req, res) => {
  const { date } = req.params;

  // Filtering
  const where = { date };

  if (req.query.course_id) {
    where.course_id = req.query.course_id;
  }

  if (req.query.status) {
    where.status = req.query.status;
  }

  // For teachers, only show attendance for their courses
  if (req.user.role === 'teacher') {
    const teacher = await Teacher.findOne({ where: { user_id: req.user.id } });
    if (teacher) {
      const teacherCourses = await Course.findAll({
        where: { teacher_id: teacher.id },
        attributes: ['id'],
      });
      where.course_id = { [Op.in]: teacherCourses.map((c) => c.id) };
    }
  }

  // Get attendance with student and course data
  const attendance = await Attendance.findAll({
    where,
    include: [
      {
        model: Student,
        as: 'student',
        attributes: ['id', 'first_name', 'last_name'],
      },
      {
        model: Course,
        as: 'course',
        attributes: ['id', 'name', 'code', 'subject'],
      },
    ],
    order: [
      [{ model: Course, as: 'course' }, 'name', 'ASC'],
      [{ model: Student, as: 'student' }, 'last_name', 'ASC'],
    ],
  });

  // Calculate summary statistics
  const totalRecords = attendance.length;
  const presentCount = attendance.filter((a) => a.status === 'Present').length;
  const absentCount = attendance.filter((a) => a.status === 'Absent').length;
  const lateCount = attendance.filter((a) => a.status === 'Late').length;
  const excusedCount = attendance.filter((a) => a.status === 'Excused').length;

  res.json({
    success: true,
    data: {
      date,
      attendance,
      summary: {
        total: totalRecords,
        present: presentCount,
        absent: absentCount,
        late: lateCount,
        excused: excusedCount,
        attendance_rate: totalRecords > 0
          ? Math.round((presentCount / totalRecords) * 10000) / 100
          : 0,
      },
    },
  });
});

/**
 * @route   GET /api/attendance/stats
 * @desc    Get attendance statistics
 * @access  Admin only
 */
exports.getAttendanceStats = catchAsync(async (req, res) => {
  const startDate = req.query.start_date;
  const endDate = req.query.end_date;

  const where = {};
  if (startDate && endDate) {
    where.date = { [Op.between]: [startDate, endDate] };
  }

  const [totalRecords, byStatus, poorAttendance] = await Promise.all([
    // Total attendance records
    Attendance.count({ where }),

    // Records by status
    Attendance.findAll({
      where,
      attributes: [
        'status',
        [Attendance.sequelize.fn('COUNT', Attendance.sequelize.col('id')), 'count'],
      ],
      group: ['status'],
    }),

    // Students with poor attendance
    Attendance.getPoorAttendance(50, { startDate, endDate }),
  ]);

  res.json({
    success: true,
    data: {
      period: { startDate, endDate },
      total: totalRecords,
      overallRate: totalRecords > 0
        ? Math.round(((byStatus.find((s) => s.status === 'Present')?.dataValues?.count || 0) / totalRecords) * 10000) / 100
        : 0,
      byStatus: byStatus.map((item) => ({
        status: item.status,
        count: parseInt(item.dataValues.count, 10),
        percentage: totalRecords > 0
          ? Math.round((parseInt(item.dataValues.count, 10) / totalRecords) * 10000) / 100
          : 0,
      })),
      poorAttendance: poorAttendance.slice(0, 10), // Top 10 students with poor attendance
    },
  });
});

/**
 * @route   POST /api/attendance/bulk
 * @desc    Mark attendance for multiple students at once
 * @access  Teacher (own courses), Admin
 */
exports.bulkMarkAttendance = catchAsync(async (req, res) => {
  const { course_id, date, records } = req.body;

  if (!course_id || !date || !Array.isArray(records) || records.length === 0) {
    throw new ValidationError('Course, date, and records array are required');
  }

  // Verify course exists
  const course = await Course.findByPk(course_id);
  if (!course) {
    throw new NotFoundError('Course not found');
  }

  // Check permissions
  if (req.user.role === 'teacher') {
    const teacher = await Teacher.findOne({ where: { user_id: req.user.id } });
    if (!teacher || course.teacher_id !== teacher.id) {
      throw new AuthorizationError('You can only mark attendance for your own courses');
    }
  }

  // Check for existing attendance records on this date
  const existingRecords = await Attendance.findAll({
    where: {
      course_id,
      date,
      student_id: { [Op.in]: records.map((r) => r.student_id) },
    },
  });

  if (existingRecords.length > 0) {
    throw new ValidationError(
      `Attendance already exists for ${existingRecords.length} student(s) on this date. `
      + 'Please update existing records instead.',
    );
  }

  // Prepare attendance records for bulk insert
  const attendanceRecords = records.map((r) => ({
    student_id: r.student_id,
    course_id,
    date,
    status: r.status,
    notes: r.notes || null,
    check_in_time: r.check_in_time || null,
    check_out_time: r.check_out_time || null,
    marked_by: req.user.id,
  }));

  // Bulk create
  const createdRecords = await Attendance.bulkCreate(attendanceRecords, {
    validate: true,
  });

  res.status(201).json({
    success: true,
    message: `Attendance marked for ${createdRecords.length} student(s)`,
    data: {
      count: createdRecords.length,
      attendance: createdRecords,
    },
  });
});

