      as: 'teacher',
      attributes: ['id', 'first_name', 'last_name', 'department'],
      include: [{
        model: User,
        as: 'user',
        attributes: ['email'],
      }],
    },
    {
      model: Class,
      as: 'class',
      attributes: ['id', 'name', 'grade_level'],
    },
  ];

  const { rows: courses, count } = await Course.findAndCountAll({
    where,
    include,
    limit,
    offset,
    order,
    distinct: true,
  });

  return res.json({
    success: true,
    data: {
      courses,
      pagination: {
        total: count,
        page,
        pages: Math.ceil(count / limit),
        limit,
      },
