    order: [[{ model: Grade, as: 'grades' }, 'score', 'DESC']],
  });

  const topTeachers = await Teacher.findAll({
    include: [{
      model: Course,
      as: 'courses',
      attributes: ['id', 'name'],
    }],
    limit: 5,
  });

  return res.json({
    success: true,
    data: {
      stats: {
        totalStudents,
        totalTeachers,
        totalCourses,
        totalClasses,
        averageGrade,
        topStudents: topStudents.map((s) => ({
          id: s.id,
          name: `${s.first_name} ${s.last_name}`,
          averageGrade: s.grades && s.grades.length > 0
            ? parseFloat((s.grades.reduce((sum, g) => sum + parseFloat(g.score || 0), 0) / s.grades.length / 10).toFixed(1))
            : 0,
        })),
        topTeachers: topTeachers.map((t) => ({
          id: t.id,
          name: `${t.first_name} ${t.last_name}`,
          coursesCount: t.courses ? t.courses.length : 0,
        })),
      },
      charts: {
        performanceData: await getPerformanceData(courseFilter),
        subjectData: await getSubjectData(courseFilter),
        gradeDistribution: await getGradeDistribution(courseFilter),
      },
      recentActivities: await getRecentActivities(courseFilter),
    },
  });
});

const { Op } = require('sequelize');
const {
  Grade, Student, Course, Teacher, User,
} = require('../models');
const {
  catchAsync, NotFoundError, ValidationError, AuthorizationError,
} = require('../middleware/errorHandler');

/**
 * @route   GET /api/grades
 * @desc    Get all grades with pagination and filtering
 * @access  Admin, Teacher (own courses)
 */
exports.getAllGrades = catchAsync(async (req, res) => {
  // Pagination
  const page = parseInt(req.query.page, 10) || 1;
  const limit = parseInt(req.query.limit, 10) || 50;
  const offset = (page - 1) * limit;

  // Filtering
  const where = {};

  if (req.query.student_id) {
    where.student_id = req.query.student_id;
  }

  if (req.query.course_id) {
    where.course_id = req.query.course_id;
  }

  if (req.query.semester) {
    where.semester = req.query.semester;
  }

  if (req.query.grade_type) {
    where.grade_type = req.query.grade_type;
  }

  if (req.query.is_published !== undefined) {
    where.is_published = req.query.is_published === 'true';
  }

  // Date range filter with validation
  if (req.query.start_date && req.query.end_date) {
    const startDate = new Date(req.query.start_date);
    const endDate = new Date(req.query.end_date);

    // Validate date range
    if (Number.isNaN(startDate.getTime()) || Number.isNaN(endDate.getTime())) {
      return res.status(400).json({
        success: false,
        message: 'Invalid date format. Please use valid dates.',
      });
    }

    if (startDate > endDate) {
      return res.status(400).json({
        success: false,
        message: 'Start date must be before or equal to end date',
      });
    }

    where.graded_date = {
      [Op.between]: [req.query.start_date, req.query.end_date],
    };
  }

  // ✅ FIXED: For students, only show their own grades
  if (req.user.role === 'student') {
    const student = await Student.findOne({ where: { user_id: req.user.id } });
    if (student) {
      where.student_id = student.id;
    } else {
      // Student profile not found, return empty
      return res.json({
        success: true,
        data: {
          grades: [],
          pagination: {
            total: 0, page: 1, pages: 0, limit,
          },
        },
      });
    }
  }

  // For teachers, only show grades for their courses
  if (req.user.role === 'teacher') {
    const teacher = await Teacher.findOne({ where: { user_id: req.user.id } });
    if (teacher) {
      const teacherCourses = await Course.findAll({
        where: { teacher_id: teacher.id },
        attributes: ['id'],
      });
      where.course_id = { [Op.in]: teacherCourses.map((c) => c.id) };
    }
  }

  // Sorting with whitelist validation to prevent SQL injection
  const order = [];
  if (req.query.sort) {
    const sortField = req.query.sort.startsWith('-')
      ? req.query.sort.substring(1)
      : req.query.sort;
    const sortOrder = req.query.sort.startsWith('-') ? 'DESC' : 'ASC';

    // Whitelist of allowed sort fields
    const allowedSortFields = ['grade_id', 'score', 'grade_type', 'graded_date', 'semester', 'weight', 'created_at', 'updated_at'];

    if (allowedSortFields.includes(sortField)) {
      order.push([sortField, sortOrder]);
    } else {
      // If invalid sort field, use default
      order.push(['graded_date', 'DESC']);
    }
  } else {
    order.push(['graded_date', 'DESC']);
  }

  // Include related data
  const include = [
    {
      model: Student,
      as: 'student',
      attributes: ['id', 'first_name', 'last_name'],
      include: [{
        model: User,
        as: 'user',
        attributes: ['email'],
      }],
    },
    {
      model: Course,
      as: 'course',
      attributes: ['id', 'name', 'code', 'subject'],
    },
  ];

  const { rows: grades, count } = await Grade.findAndCountAll({
    where,
    include,
    limit,
    offset,
    order,
    distinct: true,
  });

  return res.json({
    success: true,
    data: {
      grades,
      pagination: {
        total: count,
        page,
        pages: Math.ceil(count / limit),
        limit,
      },
    },
  });
});

/**
