/**
 * @route   GET /api/students/stats
 * @desc    Get student statistics
 * @access  Admin only
 */
exports.getStudentStats = catchAsync(async (req, res) => {
  const [total, active, assigned, unassigned, byGender] = await Promise.all([
    Student.count(),
    Student.count({
      include: [{
        model: User,
        as: 'user',
        where: { is_active: true },
      }],
    }),
    Student.count({
      where: { class_id: { [Op.ne]: null } },
    }),
    Student.count({
      where: { class_id: null },
    }),
    Student.findAll({
      attributes: [
        'gender',
        [Student.sequelize.fn('COUNT', Student.sequelize.col('id')), 'count'],
      ],
      where: {
        gender: { [Op.ne]: null },
      },
      group: ['gender'],
    }),
  ]);

  res.json({
    success: true,
    data: {
      total,
      active,
      assigned,
      unassigned,
      byGender: byGender.map((g) => ({
        gender: g.gender,
        count: parseInt(g.dataValues.count, 10),
      })),
    },
  });
});

const { Op } = require('sequelize');
const { Teacher, User } = require('../models');
const {
  catchAsync, NotFoundError, ConflictError, ValidationError, AuthorizationError,
} = require('../middleware/errorHandler');

/**
 * @route   GET /api/teachers
 * @desc    Get all teachers with pagination and filtering
 * @access  Public (filtered by active status for non-admins)
 */
exports.getAllTeachers = catchAsync(async (req, res) => {
  // Pagination
  const page = parseInt(req.query.page, 10) || 1;
  const limit = parseInt(req.query.limit, 10) || 10;
  const offset = (page - 1) * limit;

  // Filtering
  const where = {};

  if (req.query.department) {
    where.department = req.query.department;
  }

  // Search by name
  if (req.query.search) {
    where[Op.or] = [
      { first_name: { [Op.iLike]: `%${req.query.search}%` } },
      { last_name: { [Op.iLike]: `%${req.query.search}%` } },
    ];
  }

  // Sorting with whitelist validation to prevent SQL injection
  const order = [];
  if (req.query.sort) {
    const sortField = req.query.sort.startsWith('-')
      ? req.query.sort.substring(1)
      : req.query.sort;
    const sortOrder = req.query.sort.startsWith('-') ? 'DESC' : 'ASC';

    // Whitelist of allowed sort fields
    const allowedSortFields = ['teacher_id', 'first_name', 'last_name', 'department', 'hire_date', 'specialization', 'created_at', 'updated_at'];

    if (allowedSortFields.includes(sortField)) {
      order.push([sortField, sortOrder]);
    } else {
      // If invalid sort field, use default
      order.push(['last_name', 'ASC']);
    }
  } else {
    order.push(['last_name', 'ASC']);
  }

  // Include user data
  const include = [
    {
      model: User,
      as: 'user',
      attributes: ['id', 'email', 'is_active'],
      where: req.user?.role === 'admin'
        ? {}
        : { is_active: true }, // Non-admins only see active teachers
    },
  ];

  // Query
  const { count, rows } = await Teacher.findAndCountAll({
    where,
    include,
    limit,
    offset,
    order,
  });

  res.json({
    success: true,
    data: {
      teachers: rows,
      pagination: {
        total: count,
        page,
        pages: Math.ceil(count / limit),
        limit,
      },
    },
  });
});

