/**
 * Assignment Model
 * ================
 * Represents homework, quizzes, and exams
 */

const { DataTypes } = require('sequelize');
const { sequelize } = require('../config/database');

const Assignment = sequelize.define('Assignment', {
  id: {
    type: DataTypes.UUID,
    defaultValue: DataTypes.UUIDV4,
    primaryKey: true,
  },

  // Basic Information
  title: {
    type: DataTypes.STRING(255),
    allowNull: false,
    validate: {
      notEmpty: { msg: 'Tiêu đề không được để trống' },
      len: { args: [3, 255], msg: 'Tiêu đề phải từ 3-255 ký tự' },
    },
  },

  description: {
    type: DataTypes.TEXT,
    allowNull: true,
  },

  instructions: {
    type: DataTypes.TEXT,
    allowNull: true,
    comment: 'Hướng dẫn chi tiết cho học sinh',
  },

  // Type & Category
  type: {
    type: DataTypes.ENUM('homework', 'quiz', 'exam', 'practice'),
    allowNull: false,
    defaultValue: 'homework',
