    type: DataTypes.INTEGER,
    allowNull: true,
    comment: 'Thời gian làm bài (giây)',
  },

  // Late submission
  is_late: {
    type: DataTypes.BOOLEAN,
    defaultValue: false,
    comment: 'Nộp muộn hay không',
  },

  late_penalty: {
    type: DataTypes.DECIMAL(5, 2),
    defaultValue: 0,
    comment: 'Phần trăm trừ điểm do nộp muộn',
  },

  // Feedback
