    allowNull: true,
    references: {
      model: 'teachers',
      key: 'id',
    },
    comment: 'Giáo viên chấm bài',
  },

  // Auto-grade flag
  auto_graded: {
    type: DataTypes.BOOLEAN,
    defaultValue: false,
    comment: 'Được chấm tự động hay không',
  },

