      const mailOptions = {
        from: process.env.SMTP_FROM || 'AI School Dashboard <noreply@school.com>',
        to: options.to,
        subject: options.subject,
        html: options.html,
        text: options.text,
      };

      const info = await this.transporter.sendMail(mailOptions);
      console.log('✅ Email sent:', info.messageId);
